installation.powershell_command:
$scenarioPluginInstaller = Join-Path ([System.IO.Path]::GetTempPath()) ('scenario-plugin-' + [guid]::NewGuid().ToString('N') + '.py')
Invoke-WebRequest -Uri 'http://127.0.0.1:8002/api/published-plugins/ffc74d9a3af9f9c6985f6ed3c4372cdb/installer.py' -OutFile $scenarioPluginInstaller -MaximumRedirection 0 -TimeoutSec 60 -ErrorAction Stop
if ((Get-FileHash -LiteralPath $scenarioPluginInstaller -Algorithm SHA256).Hash.ToLowerInvariant() -ne '8f4f905885dc539997264955f45aba02f93ac4b1adb6f21db8ca424e35a7b258') { throw '插件安装器 SHA-256 不匹配，已停止' }
python $scenarioPluginInstaller '--marketplace-url' 'http://127.0.0.1:8002/api/published-plugins/ffc74d9a3af9f9c6985f6ed3c4372cdb/marketplace.zip' '--sha256' 'c760881d559e2e328d3bd0665b12e30eb67c857441ccc780f2a342fdc08e484d' '--package-name' 'scenario-2cc9b32f732c4cafaaeb4f22811bf990' '--marketplace-name' 'scenario-2cc9b32f732c4cafaaeb4f22811bf990-marketplace' '--allow-local-http'
if ($LASTEXITCODE -ne 0) { throw '插件安装未完成，请查看上方原因' }
Remove-Item -LiteralPath $scenarioPluginInstaller

